    /**
     * Method to retrieve the Tenant via an TenantPrimaryKey.
     * @param 	id Long
     * @return 	Tenant
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Tenant handle( FindTenantQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getTenantId() );
    }
    
    /**
     * Method to retrieve a collection of all Tenants
     *
     * @param	query	FindAllTenantQuery 
     * @return 	List<Tenant> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Tenant> handle( FindAllTenantQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindTenant,
 * but only if the id matches
 *
 * @param		entity	Tenant
 */
	protected void emitFindTenant( Tenant entity ) {
		LOGGER.info("handling emitFindTenant" );
		
	    queryUpdateEmitter.emit(FindTenantQuery.class,
	                            query -> query.getFilter().getTenantId().equals(entity.getTenantId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllTenant
	 * 
	 * @param		entity	Tenant
	 */
	protected void emitFindAllTenant( Tenant entity ) {
		LOGGER.info("handling emitFindAllTenant" );
		
	    queryUpdateEmitter.emit(FindAllTenantQuery.class,
	                            query -> true,
	                            entity);
	}

